/// Separates a signature type parameter's declared name from the suffix that
/// keeps it OPAQUE while a generic target signature is related (tsc
/// compareSignaturesRelated leaves the target's own type parameters
/// uninstantiated: nothing but themselves is assignable to them). Display
/// strips the suffix, so diagnostics still print the declared name.
pub(crate) const OPAQUE_TYPE_PARAM_MARKER: char = '\u{1}';

thread_local! {
    /// Declared constraints of opaque signature type parameters, keyed by
    /// their full (suffixed) name.
    static OPAQUE_TYPE_PARAM_CONSTRAINTS: std::cell::RefCell<HashMap<std::string::String, Type>> =
        std::cell::RefCell::new(HashMap::new());
}

thread_local! {
    /// Call-site inference variance: parameters of a callback are
    /// CONTRAVARIANT positions (odd nesting depth); their candidates are
    /// kept apart and used only when no covariant candidate exists (tsc
    /// getInferredType prefers covariant inferences).
    static INFER_CONTRA_DEPTH: std::cell::Cell<u32> = const { std::cell::Cell::new(0) };
    static INFER_CONTRA: std::cell::RefCell<HashMap<std::string::String, Vec<Type>>> =
        std::cell::RefCell::new(HashMap::new());
}

pub(crate) const RELATION_CALLBACK: u8 = 1;
pub(crate) const RELATION_TARGET_METHOD: u8 = 2;

/// The declared name of a (possibly opaque) type parameter.
pub(crate) fn opaque_type_param_display(name: &str) -> &str {
    name.split(OPAQUE_TYPE_PARAM_MARKER).next().unwrap_or(name)
}
