/// Maximum recursion depth for type operations (matches TypeScript's limit).
const MAX_RECURSION_DEPTH: u32 = 50;

/// Cumulative type-instantiation budget per top-level type operation. Mirrors
/// tsc's instantiation-count limit. A pure depth limit cannot stop types that
/// grow exponentially in *size* under linear depth — e.g.
/// `type T<L,A> = A['length'] extends L ? A : T<L, [...A, ...A]>` doubles the
/// tuple every step, so at depth 30 it is already ~2^30 nodes and exhausts
/// memory long before the depth-50 cap fires. The cumulative counter catches
/// these breadth/size explosions; it resets whenever depth returns to 0 so the
/// budget scopes to each outermost type operation.
const MAX_INSTANTIATIONS: u64 = 100_000;

/// Absolute per-statement ceiling on type-operation work. Unlike
/// `INSTANTIATION_COUNT`, this counter is NEVER rolled back — a conditional's
/// `extends`-check rollback ([`restore_instantiation_budget`]) lowers only the
/// per-operation budget, so a genuinely non-terminating expansion (a self-
/// widening zod output whose check keeps getting un-charged) would otherwise
/// spin forever. This monotonic ceiling guarantees termination while staying
/// far above any legitimate `z.infer` resolution.
const MAX_TOTAL_WORK: u64 = 1_500_000;

/// Tight sub-budget for a single `concrete_object_fold` (a `z.infer` shape
/// resolution at one declaration site). A homomorphic zod output over an
/// array/enum/nested schema can expand exponentially under the depth cap;
/// this bounds ONE fold to a fraction of a second so it bails to the lenient
/// path fast instead of burning seconds per statement.
const MAX_FOLD_WORK: u64 = 400_000;

thread_local! {
    /// Generic type parameters bound while namespace declaration metadata is
    /// resolved. This is thread-local because export/type inventories are
    /// built in parallel; a checker-wide stack would serialize those workers
    /// and could leak one worker's lexical scope into another.
    static TYPE_RESOLUTION_TYPE_PARAMS:
        RefCell<Vec<rustc_hash::FxHashSet<std::string::String>>> =
        const { RefCell::new(Vec::new()) };
}

thread_local! {
    /// Parameter bindings visible to `infer_expr_type` while a method's
    /// return type is inferred from its body at class-registration time
    /// (`build_class_info` takes `&self`, so it cannot push a real scope).
    static INFER_PARAM_SCOPE: RefCell<Vec<Vec<(std::string::String, Type)>>> =
        const { RefCell::new(Vec::new()) };
}

/// Run `f` with `bindings` visible to `infer_expr_type` identifiers.
pub(crate) fn with_infer_param_scope<R>(
    bindings: Vec<(std::string::String, Type)>,
    f: impl FnOnce() -> R,
) -> R {
    INFER_PARAM_SCOPE.with(|s| s.borrow_mut().push(bindings));
    let result = f();
    INFER_PARAM_SCOPE.with(|s| {
        s.borrow_mut().pop();
    });
    result
}

/// The innermost `with_infer_param_scope` binding of `name`, if any.
pub(crate) fn infer_param_binding(name: &str) -> Option<Type> {
    INFER_PARAM_SCOPE.with(|s| {
        s.borrow().iter().rev().find_map(|frame| {
            frame
                .iter()
                .find(|(n, _)| n == name)
                .map(|(_, t)| t.clone())
        })
    })
}

thread_local! {
    /// Covariant inference candidates of the most recent
    /// `infer_type_arguments` run, per type parameter in argument order
    /// (the recorder unions them; callers with relation access pick tsc's
    /// common supertype instead).
    static INFER_COVARIANT: std::cell::RefCell<HashMap<std::string::String, Vec<Type>>> =
        std::cell::RefCell::new(HashMap::new());
    /// The covariant candidates the last completed `infer_type_arguments`
    /// collected.
    static LAST_INFER_COVARIANT: std::cell::RefCell<HashMap<std::string::String, Vec<Type>>> =
        std::cell::RefCell::new(HashMap::new());
}

thread_local! {
    /// `strictNullChecks` of the file being checked, for the static widening
    /// helpers: tsc widens `null`/`undefined` to `any` only without it.
    static WIDEN_STRICT_NULL_CHECKS: Cell<bool> = const { Cell::new(false) };
}

thread_local! {
    /// Thread-local recursion depth counter for free-standing type functions.
    static FREE_FN_DEPTH: Cell<u32> = const { Cell::new(0) };
    /// Cumulative instantiation counter, reset at each top-level type op and
    /// rolled back around throwaway conditional checks.
    static INSTANTIATION_COUNT: Cell<u64> = const { Cell::new(0) };
    /// Monotonic per-statement work ceiling — reset per statement, NEVER rolled
    /// back, so restores can't enable an unbounded recomputation loop.
    static TOTAL_WORK_COUNT: Cell<u64> = const { Cell::new(0) };
    /// When non-zero, the `TOTAL_WORK_COUNT` value at which the in-flight
    /// `concrete_object_fold` must bail — a per-fold cap layered under the
    /// global ceiling. 0 means "no active fold cap".
    static FOLD_WORK_DEADLINE: Cell<u64> = const { Cell::new(0) };
}

/// Charge one unit of monotonic total work. Returns `true` once the absolute
/// per-statement ceiling — or the tighter in-flight per-fold deadline — is hit
/// and all callers must bail.
fn charge_total_work() -> bool {
    let n = TOTAL_WORK_COUNT.with(|c| {
        let n = c.get() + 1;
        c.set(n);
        n
    });
    if n > MAX_TOTAL_WORK {
        return true;
    }
    let deadline = FOLD_WORK_DEADLINE.with(|c| c.get());
    deadline != 0 && n > deadline
}

/// `TSC_RS_DEBUG_MEMBER_CYCLE=1` — report the types that trip the
/// member-resolution cycle guards. Read once: the guards sit on a hot path and
/// an `env::var` per call would allocate and take the env lock.
pub(crate) fn debug_member_cycle() -> bool {
    static FLAG: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *FLAG.get_or_init(|| std::env::var("TSC_RS_DEBUG_MEMBER_CYCLE").is_ok())
}

/// Name a type for a diagnostic line. Deliberately shallow — the types that
/// reach the cycle guards are self-referential, so a full `Debug` is either
/// enormous or itself non-terminating.
pub(crate) fn short_type_label(ty: &Type) -> String {
    match ty {
        Type::TypeReference(name, args) if args.is_empty() => format!("{name}"),
        Type::TypeReference(name, args) => format!("{name}<{} arg(s)>", args.len()),
        Type::Union(members) => format!("union of {}", members.len()),
        Type::Intersection(members) => format!("intersection of {}", members.len()),
        Type::ObjectType(_) => "object literal type".to_string(),
        other => format!("{:?}", std::mem::discriminant(other)),
    }
}

/// Enter a recursive type operation. Returns `true` if the recursion-depth OR
/// the cumulative-instantiation budget for the current top-level operation is
/// exhausted, in which case the caller must bail (return a sentinel) WITHOUT
/// calling [`type_op_exit`]. Resets the cumulative counter when depth is 0.
pub(crate) fn type_op_enter() -> bool {
    FREE_FN_DEPTH.with(|d| {
        let depth = d.get();
        if depth >= MAX_RECURSION_DEPTH {
            return true;
        }
        // The cumulative counter is NOT reset here (it is reset per statement
        // via `reset_instantiation_budget`), so that exponential expansions
        // which return to depth 0 between levels — e.g. an infinitely recursive
        // generic alias resolved iteratively at top level — still accumulate
        // and trip the budget instead of resetting every level.
        let over = INSTANTIATION_COUNT.with(|c| {
            let n = c.get() + 1;
            c.set(n);
            n > MAX_INSTANTIATIONS
        });
        if over || charge_total_work() {
            return true;
        }
        d.set(depth + 1);
        false
    })
}

/// Reset the cumulative instantiation budget. Called at each statement boundary
/// so the budget scopes to a single statement's type checking — generous enough
/// for any legitimate type, low enough to stop pathological blow-ups before they
/// exhaust memory.
pub(crate) fn reset_instantiation_budget() {
    INSTANTIATION_COUNT.with(|c| c.set(0));
    TOTAL_WORK_COUNT.with(|c| c.set(0));
}

/// Snapshot the current instantiation count.
pub(crate) fn instantiation_budget_mark() -> u64 {
    INSTANTIATION_COUNT.with(|c| c.get())
}

/// Roll the instantiation count back DOWN to a prior mark (never up). Used to
/// un-charge a bounded, throwaway sub-computation — a conditional's `extends`
/// check deep-expands the whole ZodObject internals graph purely to decide the
/// relation, and that cost must not starve the selected branch, whose own
/// expansion is what produces the result. Peak memory stays bounded because
/// the check is still capped by the budget DURING its run and its structure is
/// dropped before the rollback. The rollback is downward-only, so it can only
/// ever GRANT the branch budget the conditional already had on entry — it never
/// resets the global counter to zero, so a genuinely unbounded expansion still
/// trips the cap.
pub(crate) fn restore_instantiation_budget(mark: u64) {
    INSTANTIATION_COUNT.with(|c| {
        if c.get() > mark {
            c.set(mark);
        }
    });
}

/// Charge one unit against the cumulative instantiation budget WITHOUT taking a
/// depth level. Returns `true` when the budget for the current top-level type
/// operation is spent and the caller must bail.
///
/// For recursive walks that already own a depth counter but still need the
/// breadth backstop — `deep_expand_for_conditional` is depth-capped yet grows
/// as the product of per-level property counts, which is precisely the
/// "exponential in size under linear depth" case `MAX_INSTANTIATIONS` exists
/// for.
pub(crate) fn charge_instantiation() -> bool {
    let over = INSTANTIATION_COUNT.with(|c| {
        let n = c.get() + 1;
        c.set(n);
        n > MAX_INSTANTIATIONS
    });
    over || charge_total_work()
}

thread_local! {
    /// Type-reference names currently being structurally expanded, innermost
    /// last. A stack rather than a set: the same name may legitimately appear
    /// in sibling positions, only re-entry along one path is a cycle.
    static EXPANDING_REFS: std::cell::RefCell<Vec<std::string::String>> =
        const { std::cell::RefCell::new(Vec::new()) };
}

/// Enter expansion of a type reference. Returns `false` if this name is already
/// being expanded on the current path (a recursive type), in which case the
/// caller must NOT call [`expansion_exit`].
pub(crate) fn expansion_enter(name: &str) -> bool {
    EXPANDING_REFS.with(|stack| {
        let mut stack = stack.borrow_mut();
        if stack.iter().any(|n| n == name) {
            return false;
        }
        stack.push(name.to_string());
        true
    })
}

/// Leave expansion of the innermost type reference.
pub(crate) fn expansion_exit() {
    EXPANDING_REFS.with(|stack| {
        stack.borrow_mut().pop();
    });
}

/// Leave a recursive type operation entered via [`type_op_enter`].
pub(crate) fn type_op_exit() {
    FREE_FN_DEPTH.with(|d| d.set(d.get().saturating_sub(1)));
}

