    // -----------------------------------------------------------------------
    // Helper for strict null checks
    // -----------------------------------------------------------------------

    fn strict_null_opts() -> CompilerOptions {
        let mut opts = CompilerOptions::default();
        opts.strict_null_checks = Some(true);
        opts
    }

    fn check_strict_no_errors(src: &str) {
        let output = parse_and_check_with_opts(src, strict_null_opts());
        assert!(
            output.diagnostics.is_empty(),
            "Expected no errors but got: {:?}",
            output.diagnostics
        );
    }

    fn check_strict_has_error(src: &str, code: u32) -> Diagnostic {
        let output = parse_and_check_with_opts(src, strict_null_opts());
        let diag = output
            .diagnostics
            .iter()
            .find(|d| d.code == code)
            .cloned()
            .unwrap_or_else(|| {
                panic!(
                    "Expected error TS{} but got diagnostics: {:?}",
                    code, output.diagnostics
                );
            });
        diag
    }

    #[test]
    fn test_ts2774_callable_truthiness_precision_and_guarded_use() {
        let source = r#"
            function test(
                fn: () => void,
                other: () => void,
                maybe?: () => void,
                dynamic: any,
                unknownValue: unknown,
            ) {
                if (fn) {}
                if (maybe) {}
                if (dynamic) {}
                if (unknownValue) {}
                if (!!fn) {}
                if (fn) { fn(); }
                if (fn && fn()) {}
                if (fn) { other(); }
            }
        "#;
        let output = parse_and_check_with_opts(source, strict_null_opts());
        let diagnostics: Vec<_> = output
            .diagnostics
            .iter()
            .filter(|diagnostic| diagnostic.code == 2774)
            .collect();
        assert_eq!(diagnostics.len(), 2, "{:#?}", output.diagnostics);
        assert!(diagnostics.iter().all(|diagnostic| {
            diagnostic.message
                == "This condition will always return true since this function is always defined. Did you mean to call it instead?"
        }));
    }

    #[test]
    fn test_ts2774_guarded_use_respects_callback_and_hoisted_shadows() {
        let source = r#"
            function test(fn: () => void) {
                if (fn) {
                    [0].forEach(fn => fn());
                }
                if (fn) {
                    (() => {
                        fn();
                        function fn() {}
                    })();
                }
                if (fn) {
                    (() => {
                        fn();
                        var fn: () => void;
                    })();
                }
                if (fn) {
                    (() => fn())();
                }
            }
        "#;
        let output = parse_and_check_with_opts(source, strict_null_opts());
        assert_eq!(
            output
                .diagnostics
                .iter()
                .filter(|diagnostic| diagnostic.code == 2774)
                .count(),
            3,
            "{:#?}",
            output.diagnostics
        );
    }

