    #[test]
    fn test_const_condition_alias_narrows_stable_dependency() {
        let src = r#"
            declare const flag: boolean;
            declare function finite(value: unknown): boolean;
            declare function take(value: number): void;
            const year: number | undefined = flag ? 2024 : undefined;
            const hasYear = year !== undefined && finite(year);
            hasYear ? take(year) : undefined;
            hasYear ? take(year + 1) : undefined;
        "#;
        check_strict_no_errors(src);
    }

    #[test]
    fn test_const_condition_alias_does_not_narrow_mutable_dependency() {
        let src = r#"
            declare function take(value: number): void;
            let year: number | undefined = 2024;
            const hasYear = year !== undefined;
            year = undefined;
            hasYear ? take(year) : undefined;
        "#;
        check_strict_has_error(src, 2345);
    }

    #[test]
    fn test_const_condition_alias_does_not_narrow_shadowing_dependency() {
        let src = r#"
            declare const flag: boolean;
            declare function take(value: number): void;
            const year: number | undefined = flag ? 2024 : undefined;
            const hasYear = year !== undefined;
            {
                const year = "not a number";
                hasYear ? take(year) : undefined;
            }
        "#;
        check_strict_has_error(src, 2345);
    }

