    /// Regression: when two unrelated files export a same-named top-level
    /// `const` / `let`, an untyped mock in a regular `.ts` source must NOT
    /// shadow the authoritative declaration coming from a `.d.ts` file.
    ///
    /// Before the fix:
    ///   * `inject_external_types` walked every project file and called
    ///     `declare_var(name, ty)` unconditionally — last-write-wins.
    ///   * For a large monorepo the mock at
    ///     `apps/app/src/components/app/mock-db.ts` (`export const db = {…}`)
    ///     clobbered the real `declare const prisma: PrismaClient` from
    ///     `packages/db/dist/...`, leaking phantom TS2339 ("Property
    ///     'tenant' / 'booking' / 'calendarEvent' does not exist") across
    ///     every route handler that did `db.<model>.<op>`.
    ///
    /// After the fix:
    ///   * `inject_external_types` runs in two passes (`.d.ts` first,
    ///     then `.ts`).
    ///   * `inject_stmt::Var` is first-wins. Authoritative ambient
    ///     declarations from `.d.ts` always land before any user-source
    ///     re-declaration, and the mock can't overwrite them.
    #[test]
    fn test_inject_dts_wins_over_ts_for_same_name_var() {
        let dts = tsc_rs_parser::parse(
            "pkg.d.ts",
            "export interface Db { tenant: { findFirst(): Promise<unknown> } }\n\
             export declare const db: Db;",
        );
        let ts_mock = tsc_rs_parser::parse(
            "mock.ts",
            "export const db = { delete: (_t: any) => ({ where: (_c: any) => Promise.resolve() }) };",
        );
        let route = tsc_rs_parser::parse(
            "route.ts",
            "import { db } from './pkg';\n\
             async function go() { return db.tenant.findFirst(); }",
        );

        let dts_sym = tsc_rs_symbols::bind(&dts);
        let ts_mock_sym = tsc_rs_symbols::bind(&ts_mock);
        let route_sym = tsc_rs_symbols::bind(&route);
        let _ = dts_sym;
        let _ = ts_mock_sym;
        let _ = route_sym;

        let mut checker = TypeChecker::new();
        checker.inject_external_types(&[&dts, &ts_mock, &route]);
        // Per-file check of the route in a cloned checker (mirrors how
        // tsc_rs_project::compile_selected runs).
        let mut per_file = checker.clone();
        let out = per_file.check(&route, &tsc_rs_symbols::bind(&route));
        let ts2339: Vec<_> = out.diagnostics.iter().filter(|d| d.code == 2339).collect();
        assert!(
            ts2339.is_empty(),
            "Expected no TS2339 (mock shadow) but got: {:?}",
            ts2339
        );

        // Verify file ordering is irrelevant — `.d.ts` always wins.
        let mut checker2 = TypeChecker::new();
        checker2.inject_external_types(&[&ts_mock, &dts, &route]);
        let mut per_file2 = checker2.clone();
        let out2 = per_file2.check(&route, &tsc_rs_symbols::bind(&route));
        let ts2339_b: Vec<_> = out2.diagnostics.iter().filter(|d| d.code == 2339).collect();
        assert!(
            ts2339_b.is_empty(),
            "Expected order-independence (mock first) but got: {:?}",
            ts2339_b
        );
    }

    /// Regression: an exported interface in a declaration module is scoped to
    /// that module. It must not replace a same-named Web API global for files
    /// that did not import it. In a large Next.js app, Express's
    /// `Response.status(code)` shadowed lib.dom's numeric `Response.status`,
    /// making `res.status` from `fetch()` look like a method.
    #[test]
    fn test_injected_module_interface_does_not_shadow_builtin_global() {
        let dom = tsc_rs_parser::parse(
            "lib.dom.d.ts",
            "interface Response { readonly ok: boolean; readonly status: number }\n\
             declare function fetch(input: string): Promise<Response>;",
        );
        let express = tsc_rs_parser::parse(
            "express.d.ts",
            "export interface Response { status(code: number): this }",
        );
        let route = tsc_rs_parser::parse(
            "route.ts",
            "async function ping() {\n\
                 const res = await fetch('https://worker.example');\n\
                 const statusCode: number = res.status;\n\
             }",
        );

        for files in [[&dom, &express, &route], [&express, &dom, &route]] {
            let mut checker = TypeChecker::new();
            checker.inject_external_types(&files);
            let express_exports = checker
                .lookup_module_exports("express.d.ts")
                .expect("expected Express module exports");
            let express_response = express_exports
                .iter()
                .find(|(name, _)| name == "Response")
                .map(|(_, ty)| ty)
                .expect("expected exported Express Response");
            assert!(
                matches!(
                    express_response,
                    Type::ObjectType(info)
                        if info.properties.iter().any(
                            |(name, ty)| name == "status" && matches!(ty.as_ref(), Type::Function(_))
                        )
                ),
                "Expected a precise module-scoped Express Response: {:?}",
                express_response
            );
            let per_file = checker.clone();
            let out = per_file.check(&route, &tsc_rs_symbols::bind(&route));
            let ts2322: Vec<_> = out.diagnostics.iter().filter(|d| d.code == 2322).collect();
            assert!(
                ts2322.is_empty(),
                "Expected lib.dom Response.status to remain numeric: {:?}",
                ts2322
            );
        }
    }

    /// Regression: an imported interface in a heritage clause must resolve
    /// from its source module, not from the first same-named interface in the
    /// project-wide donor. date-fns's `FormatOptions extends ContextOptions`
    /// used to inherit Istanbul's five required report fields instead of
    /// date-fns's optional date context.
    #[test]
    fn test_interface_extends_uses_import_source_provenance() {
        let dir = std::env::temp_dir().join(format!(
            "tsc-rs-imported-interface-extends-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();

        let istanbul_path = dir.join("istanbul.d.ts");
        let types_path = dir.join("types.d.ts");
        let format_path = dir.join("format.d.ts");
        let fr_path = dir.join("fr.d.ts");
        let route_path = dir.join("route.ts");
        let istanbul_src = "export interface ContextOptions {\n\
            coverageMap: unknown;\n\
            dir: string;\n\
        }\n";
        let types_src = "export interface Locale {\n\
            options?: number;\n\
            localize: string;\n\
            formatLong: string;\n\
        }\n\
        export interface LocalizedOptions<K extends keyof Locale> {\n\
            locale?: Pick<Locale, K>;\n\
        }\n\
        export interface ContextOptions<D> { in?: (value: Date) => D; }\n\
        export interface RequiredOptions { requiredFlag: string; }\n";
        let format_src = "import type {\n\
            ContextOptions,\n\
            LocalizedOptions,\n\
            RequiredOptions,\n\
        } from './types';\n\
        export interface FormatOptions\n\
            extends LocalizedOptions<'options' | 'localize' | 'formatLong'>,\n\
                ContextOptions<Date>,\n\
                RequiredOptions {}\n\
        export declare function format(options?: FormatOptions): void;\n";
        let fr_src = "import type { Locale } from './types';\n\
            export declare const fr: Locale;\n";
        let route_src = "import { format } from './format';\n\
            import { fr } from './fr';\n\
            format({ locale: fr, requiredFlag: 'ok' });\n\
            format({ locale: fr });\n";
        for (path, source) in [
            (&istanbul_path, istanbul_src),
            (&types_path, types_src),
            (&format_path, format_src),
            (&fr_path, fr_src),
            (&route_path, route_src),
        ] {
            std::fs::write(path, source).unwrap();
        }

        let istanbul = tsc_rs_parser::parse(istanbul_path.to_str().unwrap(), istanbul_src);
        let types = tsc_rs_parser::parse(types_path.to_str().unwrap(), types_src);
        let format = tsc_rs_parser::parse(format_path.to_str().unwrap(), format_src);
        let fr = tsc_rs_parser::parse(fr_path.to_str().unwrap(), fr_src);
        let route = tsc_rs_parser::parse(route_path.to_str().unwrap(), route_src);

        for files in [
            [&istanbul, &types, &format, &fr, &route],
            [&types, &istanbul, &format, &fr, &route],
        ] {
            let mut checker = TypeChecker::new();
            checker.inject_external_types(&files);
            let out = checker.clone().check(&route, &tsc_rs_symbols::bind(&route));
            let ts2345: Vec<_> = out.diagnostics.iter().filter(|d| d.code == 2345).collect();
            assert_eq!(
                ts2345.len(),
                1,
                "the valid date-fns-shaped call must pass while the call missing the genuinely required imported member still fails: {:?}",
                out.diagnostics,
            );
        }
        std::fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn test_type_only_import_does_not_use_unrelated_unparsed_interface() {
        let dir =
            std::env::temp_dir().join(format!("tsc-rs-duplicate-interface-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let rich_path = dir.join("a-rich.ts");
        let narrow_path = dir.join("z-narrow.ts");
        let route_path = dir.join("route.ts");
        let rich_src = "export interface ServiceDependencies {\n\
            getAuthenticatedUser(): Promise<unknown>;\n\
            getAuthUser(): unknown;\n\
            getServiceContext(): unknown;\n\
        }\n";
        let narrow_src =
            "export interface ServiceDependencies { getAuthenticatedUser(): Promise<unknown>; }\n";
        let route_src = "import type { ServiceDependencies } from './a-rich';\n\
            const deps: ServiceDependencies = {\n\
                getAuthenticatedUser: async () => ({}),\n\
                getAuthUser: () => ({}),\n\
                getServiceContext: () => ({}),\n\
            };\n";
        std::fs::write(&rich_path, rich_src).unwrap();
        std::fs::write(&narrow_path, narrow_src).unwrap();
        std::fs::write(&route_path, route_src).unwrap();

        let narrow = tsc_rs_parser::parse(narrow_path.to_str().unwrap(), narrow_src);
        let route = tsc_rs_parser::parse(route_path.to_str().unwrap(), route_src);

        let mut checker = TypeChecker::new();
        // The imported workspace source exists for module resolution but is
        // deliberately absent from the donor, matching projects whose
        // tsconfig includes only their own package and whose dependency
        // publishes `.ts` rather than `.d.ts` types.
        checker.inject_external_types(&[&narrow, &route]);
        let out = checker.clone().check(&route, &tsc_rs_symbols::bind(&route));
        assert!(
            out.diagnostics.is_empty(),
            "the imported module's interface must win over a same-named declaration: {:?}",
            out.diagnostics
        );
        std::fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn test_same_file_alias_wins_over_unrelated_interface() {
        let coupon = tsc_rs_parser::parse(
            "coupons.ts",
            r#"
            type ValidationResult =
                | { success: true; value: number }
                | { success: false; reason: string };
            async function validate(): Promise<ValidationResult> {
                return { success: false, reason: "invalid" };
            }
            async function invalid(): Promise<ValidationResult> {
                return { success: true };
            }
        "#,
        );
        let unrelated = tsc_rs_parser::parse(
            "shipping.ts",
            r#"
            interface ValidationResult {
                valid: boolean;
                errors: string[];
            }
        "#,
        );
        let mut checker = TypeChecker::new();
        checker.inject_external_types(&[&coupon, &unrelated]);
        let out = checker.check(&coupon, &tsc_rs_symbols::bind(&coupon));
        let assignment_errors: Vec<_> = out.diagnostics.iter().filter(|d| d.code == 2322).collect();
        assert_eq!(
            assignment_errors.len(),
            1,
            "the valid return must use the same-file alias while its genuinely incomplete sibling still fails: {:?}",
            out.diagnostics,
        );
    }

    /// Regression: `export { x as y } from "./mod"` aliased re-exports
    /// must populate the global scope with `y` aliased to the type of `x`,
    /// across an arbitrary chain of `.d.ts` files. Otherwise a `.ts`
    /// mock at the project edge would slot into the empty `db` binding
    /// and shadow what should have been `PrismaClient` via the chain
    /// `pkg/index.d.ts -> pkg/client.d.ts -> declare const prisma: PrismaClient`.
    #[test]
    fn test_aliased_reexport_chain_dts() {
        let internal = tsc_rs_parser::parse(
            "pkg/internal.d.ts",
            "export interface PrismaClient { tenant: { findFirst(): Promise<unknown> } }",
        );
        let client = tsc_rs_parser::parse(
            "pkg/client.d.ts",
            "import { PrismaClient } from './internal';\n\
             export declare const prisma: PrismaClient;\n\
             export { PrismaClient };",
        );
        let index =
            tsc_rs_parser::parse("pkg/index.d.ts", "export { prisma as db } from './client';");
        let mock = tsc_rs_parser::parse(
            "mock.ts",
            "export const db = { delete: (_t: any) => ({ where: (_c: any) => Promise.resolve() }) };",
        );
        let route = tsc_rs_parser::parse(
            "route.ts",
            "import { db } from './pkg';\nasync function go() { return db.tenant.findFirst(); }",
        );

        let mut checker = TypeChecker::new();
        checker.inject_external_types(&[&internal, &client, &index, &mock, &route]);
        let mut per_file = checker.clone();
        let out = per_file.check(&route, &tsc_rs_symbols::bind(&route));
        let ts2339: Vec<_> = out.diagnostics.iter().filter(|d| d.code == 2339).collect();
        assert!(
            ts2339.is_empty(),
            "Expected no TS2339 (aliased re-export chain) but got: {:?}",
            ts2339
        );

        // Permute file order — closure must converge regardless.
        let mut checker2 = TypeChecker::new();
        checker2.inject_external_types(&[&mock, &index, &internal, &route, &client]);
        let mut per_file2 = checker2.clone();
        let out2 = per_file2.check(&route, &tsc_rs_symbols::bind(&route));
        let ts2339_b: Vec<_> = out2.diagnostics.iter().filter(|d| d.code == 2339).collect();
        assert!(
            ts2339_b.is_empty(),
            "Expected order-independence (permuted) but got: {:?}",
            ts2339_b
        );
    }

    /// A type reference through a namespace import must remain a qualified
    /// reference rather than being erased to `any`. This is the front half of
    /// Zod's `core.output<this>` resolution; the Zod integration tests cover
    /// the subsequent cross-file generic/conditional expansion.
    #[test]
    fn test_namespace_qualified_type_reference_is_not_erased_to_any() {
        let file = tsc_rs_parser::parse(
            "test.ts",
            r#"
                import * as core from "./core";
                type Result = core.output<string>;
            "#,
        );
        let out = TypeChecker::new().check(&file, &tsc_rs_symbols::bind(&file));
        assert!(
            out.expression_types
                .values()
                .any(|ty| ty == "type_alias_body=core.output<string>"),
            "expected the qualified alias body to be preserved, got: {:?}",
            out.expression_types
        );
    }

    /// Regression: `new Foo(...)` against a class extending a base that is
    /// not in `class_info` (e.g. `Response` from lib.dom, declared as
    /// `interface + var`) used to fire a phantom TS2554 "Expected 0
    /// arguments". The constructor is unknown to ts-rs, so we cannot
    /// validate arity — bail rather than treat as "0 params".
    #[test]
    fn test_new_class_extending_unknown_base_does_not_fire_ts2554() {
        check_no_errors(
            r#"
            class MyResponse extends Response {
                static helper() {
                    return new MyResponse("body", { status: 200 });
                }
            }
            const r = new MyResponse(null, { status: 204 });
        "#,
        );
    }

    /// Regression: when two unrelated files declare the same class name,
    /// the one carrying an explicit constructor must win over a no-ctor
    /// shim. Previously a no-ctor shim could shadow the real declaration
    /// and break every `new Foo(...)` callsite with TS2554.
    ///
    /// The test triggers TS2300 (duplicate identifier) because both classes
    /// live in the same source — that diagnostic is fine and expected. The
    /// regression is specifically about the TS2554 phantom arg-count error
    /// that used to leak out when the no-ctor shim won the race.
    #[test]
    fn test_class_with_explicit_ctor_beats_no_ctor_namesake() {
        let out = parse_and_check(
            r#"
            class Widget extends Response {}
            class Widget {
                constructor(a: string, b: number) {}
            }
            const w = new Widget("hi", 42);
        "#,
        );
        let ts2554: Vec<_> = out.diagnostics.iter().filter(|d| d.code == 2554).collect();
        assert!(
            ts2554.is_empty(),
            "Expected no TS2554 (phantom arg count) but got: {:?}",
            ts2554
        );
    }

