    #[test]
    fn test_substitute_function_type() {
        // A function's OWN type param SHADOWS a same-named entry in the map.
        // Substituting `{T: Number}` into `<T>(x: T): T` must leave it UNCHANGED
        // — the `T` inside is the method's independent generic, not the outer
        // one. (The old behavior — bind and drop `T` — is the class/method
        // type-param collision that made `.or<T>` on `ZodOptional<T=ZodString>`
        // report "not assignable to ZodString".)
        let mut map = HashMap::new();
        map.insert("T".to_string(), Type::Number);
        let ft = Type::Function(FunctionType {
            params: vec![("x".to_string(), Type::TypeParameter("T".to_string()))],
            return_type: Arc::new(Type::TypeParameter("T".to_string())),
            type_params: vec!["T".to_string()],
            type_param_defaults: Vec::new(),
            type_param_constraints: Vec::new(),
            type_predicate: None,
        });
        match TypeChecker::substitute(&ft, &map) {
            Type::Function(sub_ft) => {
                assert_eq!(
                    sub_ft.params[0].1,
                    Type::TypeParameter("T".to_string()),
                    "shadowed T must not be substituted in params"
                );
                assert_eq!(
                    *sub_ft.return_type,
                    Type::TypeParameter("T".to_string()),
                    "shadowed T must not be substituted in return"
                );
                assert_eq!(
                    sub_ft.type_params,
                    vec!["T".to_string()],
                    "the method's own type param must be preserved"
                );
            }
            _ => panic!("Expected Function type"),
        }

        // A map key NOT shadowed by the function's params IS substituted, and
        // the function's own param is still preserved: `<T>(x: U): T` + {U:Bool}
        // -> `<T>(x: boolean): T`.
        let mut map2 = HashMap::new();
        map2.insert("U".to_string(), Type::Boolean);
        let ft2 = Type::Function(FunctionType {
            params: vec![("x".to_string(), Type::TypeParameter("U".to_string()))],
            return_type: Arc::new(Type::TypeParameter("T".to_string())),
            type_params: vec!["T".to_string()],
            type_param_defaults: Vec::new(),
            type_param_constraints: Vec::new(),
            type_predicate: None,
        });
        match TypeChecker::substitute(&ft2, &map2) {
            Type::Function(sub_ft) => {
                assert_eq!(
                    sub_ft.params[0].1,
                    Type::Boolean,
                    "non-shadowed U substituted"
                );
                assert_eq!(*sub_ft.return_type, Type::TypeParameter("T".to_string()));
                assert_eq!(sub_ft.type_params, vec!["T".to_string()]);
            }
            _ => panic!("Expected Function type"),
        }
    }

