    #[test]
    fn test_inference_does_not_pair_different_type_reference_wrappers() {
        let callback_arg = Type::Function(FunctionType {
            params: Vec::new(),
            return_type: Arc::new(Type::Union(
                vec![
                    Type::Number,
                    Type::TypeReference("Box".to_string(), vec![Type::String].into()),
                ]
                .into(),
            )),
            type_params: Vec::new(),
            type_param_defaults: Vec::new(),
            type_param_constraints: Vec::new(),
            type_predicate: None,
        });
        let callback_param = Type::Function(FunctionType {
            params: Vec::new(),
            return_type: Arc::new(Type::Union(
                vec![
                    Type::TypeParameter("T".to_string()),
                    Type::TypeReference(
                        "Promise".to_string(),
                        vec![Type::TypeParameter("T".to_string())].into(),
                    ),
                ]
                .into(),
            )),
            type_params: Vec::new(),
            type_param_defaults: Vec::new(),
            type_param_constraints: Vec::new(),
            type_predicate: None,
        });
        let result = TypeChecker::infer_type_arguments(
            &[callback_arg],
            &[("callback".to_string(), callback_param.clone())],
            &["T".to_string()],
        );
        assert_eq!(
            result.get("T"),
            Some(&Type::Union(
                vec![
                    Type::Number,
                    Type::TypeReference("Box".to_string(), vec![Type::String].into()),
                ]
                .into(),
            )),
            "Box<string> must contribute as a whole branch, not infer string through Promise<T>"
        );

        let promised_callback_arg = Type::Function(FunctionType {
            params: Vec::new(),
            return_type: Arc::new(Type::Union(
                vec![
                    Type::Number,
                    Type::TypeReference("Promise".to_string(), vec![Type::String].into()),
                ]
                .into(),
            )),
            type_params: Vec::new(),
            type_param_defaults: Vec::new(),
            type_param_constraints: Vec::new(),
            type_predicate: None,
        });
        let promised_result = TypeChecker::infer_type_arguments(
            &[promised_callback_arg],
            &[("callback".to_string(), callback_param)],
            &["T".to_string()],
        );
        assert_eq!(
            promised_result.get("T"),
            Some(&Type::Union(vec![Type::String, Type::Number].into())),
            "a genuinely matching Promise<string> branch must still infer its inner string"
        );
    }

