    // -----------------------------------------------------------------------
    // Mapped & conditional type evaluation tests
    // -----------------------------------------------------------------------

    fn make_obj(props: Vec<(&str, Type)>) -> Type {
        Type::ObjectType(ObjectTypeInfo {
            properties: props
                .into_iter()
                .map(|(n, t)| (n.to_string(), Arc::new(t)))
                .collect(),
            call_signatures: Vec::new(),
            construct_signatures: Vec::new(),
            index_signature: None,
            index_signature_name: None,
            method_names: Vec::new(),
        })
    }

    // --- keyof_type ---

    #[test]
    fn test_keyof_object_type() {
        let obj = make_obj(vec![("a", Type::Number), ("b", Type::String)]);
        let result = keyof_type(&obj);
        match result {
            Type::Union(members) => {
                assert_eq!(members.len(), 2);
                assert!(members.contains(&Type::StringLiteral("a".to_string())));
                assert!(members.contains(&Type::StringLiteral("b".to_string())));
            }
            _ => panic!("Expected union of string literals, got {:?}", result),
        }
    }

    #[test]
    fn test_keyof_single_prop() {
        let obj = make_obj(vec![("x", Type::Number)]);
        let result = keyof_type(&obj);
        assert_eq!(result, Type::StringLiteral("x".to_string()));
    }

    #[test]
    fn test_keyof_empty_object() {
        let obj = make_obj(vec![]);
        assert_eq!(keyof_type(&obj), Type::Never);
    }

    #[test]
    fn test_keyof_any() {
        let result = keyof_type(&Type::Any);
        match result {
            Type::Union(members) => {
                assert!(members.contains(&Type::String));
                assert!(members.contains(&Type::Number));
                assert!(members.contains(&Type::Symbol));
            }
            _ => panic!("Expected union for keyof any"),
        }
    }

    #[test]
    fn test_keyof_primitive() {
        assert_eq!(keyof_type(&Type::Number), Type::Never);
        assert_eq!(keyof_type(&Type::String), Type::Never);
    }

