    // --- evaluate_mapped_type / Partial<T> ---

    #[test]
    fn test_partial_like_mapped_type() {
        // Partial<T> = { [P in keyof T]?: T[P] }
        // T = { a: number; b: string }
        let t_type = make_obj(vec![("a", Type::Number), ("b", Type::String)]);

        let mut type_args = HashMap::new();
        type_args.insert("T".to_string(), t_type);

        // constraint = keyof T, template = T[P]
        let constraint = Type::Keyof(Arc::new(Type::TypeParameter("T".to_string())));
        let template = Type::IndexedAccess(
            Arc::new(Type::TypeParameter("T".to_string())),
            Arc::new(Type::TypeParameter("P".to_string())),
        );

        let result = evaluate_mapped_type(
            "P",
            &constraint,
            Some(&template),
            None,
            None,
            Some(MappedModifierKind::Add),
            &type_args,
        );

        if let Type::ObjectType(info) = &result {
            assert_eq!(info.properties.len(), 2);
            // Partial's `?` modifier wraps each value as Optional (the old
            // behavior ignored the modifier and left them required — a bug).
            assert!(info.properties.iter().any(|(n, t)| n == "a"
                && matches!(t.as_ref(), Type::Optional(inner) if **inner == Type::Number)));
            assert!(info.properties.iter().any(|(n, t)| n == "b"
                && matches!(t.as_ref(), Type::Optional(inner) if **inner == Type::String)));
        } else {
            panic!("Expected ObjectType, got {:?}", result);
        }
    }

    #[test]
    fn test_required_like_mapped_type() {
        // Required<T> = { [P in keyof T]-?: T[P] }
        let t_type = make_obj(vec![("x", Type::Number), ("y", Type::String)]);
        let mut type_args = HashMap::new();
        type_args.insert("T".to_string(), t_type);

        let constraint = Type::Keyof(Arc::new(Type::TypeParameter("T".to_string())));
        let template = Type::IndexedAccess(
            Arc::new(Type::TypeParameter("T".to_string())),
            Arc::new(Type::TypeParameter("P".to_string())),
        );

        let result = evaluate_mapped_type(
            "P",
            &constraint,
            Some(&template),
            None,
            None,
            Some(MappedModifierKind::Remove),
            &type_args,
        );

        if let Type::ObjectType(info) = &result {
            assert_eq!(info.properties.len(), 2);
        } else {
            panic!("Expected ObjectType");
        }
    }

    #[test]
    fn test_readonly_like_mapped_type() {
        // Readonly<T> = { readonly [P in keyof T]: T[P] }
        let t_type = make_obj(vec![("a", Type::Number)]);
        let mut type_args = HashMap::new();
        type_args.insert("T".to_string(), t_type);

        let constraint = Type::Keyof(Arc::new(Type::TypeParameter("T".to_string())));
        let template = Type::IndexedAccess(
            Arc::new(Type::TypeParameter("T".to_string())),
            Arc::new(Type::TypeParameter("P".to_string())),
        );

        let result = evaluate_mapped_type(
            "P",
            &constraint,
            Some(&template),
            None,
            Some(MappedModifierKind::Add),
            None,
            &type_args,
        );

        if let Type::ObjectType(info) = &result {
            assert_eq!(info.properties.len(), 1);
            assert_eq!(*info.properties[0].1, Type::Number);
        } else {
            panic!("Expected ObjectType");
        }
    }

    // --- Pick<T, K> ---

    #[test]
    fn test_pick_like_mapped_type() {
        // Pick<T, K extends keyof T> = { [P in K]: T[P] }
        // T = { a: number; b: string; c: boolean }, K = "a" | "c"
        let t_type = make_obj(vec![
            ("a", Type::Number),
            ("b", Type::String),
            ("c", Type::Boolean),
        ]);

        let k_type = Type::Union(
            vec![
                Type::StringLiteral("a".to_string()),
                Type::StringLiteral("c".to_string()),
            ]
            .into(),
        );

        let mut type_args = HashMap::new();
        type_args.insert("T".to_string(), t_type);
        type_args.insert("K".to_string(), k_type.clone());

        let constraint = Type::TypeParameter("K".to_string());
        let template = Type::IndexedAccess(
            Arc::new(Type::TypeParameter("T".to_string())),
            Arc::new(Type::TypeParameter("P".to_string())),
        );

        let result = evaluate_mapped_type(
            "P",
            &constraint,
            Some(&template),
            None,
            None,
            None,
            &type_args,
        );

        if let Type::ObjectType(info) = &result {
            assert_eq!(info.properties.len(), 2);
            assert!(info
                .properties
                .iter()
                .any(|(n, t)| n == "a" && **t == Type::Number));
            assert!(info
                .properties
                .iter()
                .any(|(n, t)| n == "c" && **t == Type::Boolean));
            // "b" should not be present
            assert!(!info.properties.iter().any(|(n, _)| n == "b"));
        } else {
            panic!("Expected ObjectType, got {:?}", result);
        }
    }

    // --- Exclude<U, T> (conditional type) ---

    #[test]
    fn test_exclude_conditional_type() {
        // Exclude<U, T> = U extends T ? never : U
        // Exclude<"a" | "b" | "c", "a"> = "b" | "c"
        let check = Type::TypeParameter("U".to_string());
        let extends = Type::TypeParameter("T".to_string());
        let true_type = Type::Never;
        let false_type = Type::TypeParameter("U".to_string());

        let mut type_args = HashMap::new();
        type_args.insert(
            "U".to_string(),
            Type::Union(
                vec![
                    Type::StringLiteral("a".to_string()),
                    Type::StringLiteral("b".to_string()),
                    Type::StringLiteral("c".to_string()),
                ]
                .into(),
            ),
        );
        type_args.insert("T".to_string(), Type::StringLiteral("a".to_string()));

        let result =
            evaluate_conditional_type(&check, &extends, &true_type, &false_type, &type_args);

        match result {
            Type::Union(members) => {
                assert_eq!(members.len(), 2);
                assert!(members.contains(&Type::StringLiteral("b".to_string())));
                assert!(members.contains(&Type::StringLiteral("c".to_string())));
            }
            _ => panic!("Expected union of 'b' | 'c', got {:?}", result),
        }
    }

