    // --- Omit<T, K> via mapped + conditional (Exclude on keys) ---

    #[test]
    fn test_omit_like_type() {
        // Omit<T, K> = Pick<T, Exclude<keyof T, K>>
        // = { [P in Exclude<keyof T, K>]: T[P] }
        // T = { a: number; b: string; c: boolean }, K = "b"
        let t_type = make_obj(vec![
            ("a", Type::Number),
            ("b", Type::String),
            ("c", Type::Boolean),
        ]);

        // First compute Exclude<keyof T, K>
        let mut args = HashMap::new();
        args.insert("T".to_string(), t_type.clone());

        // keyof T = "a" | "b" | "c"
        let keyof_t = keyof_type(&t_type);

        // Exclude = U extends T ? never : U
        // where U = keyof T, T = "b"
        let mut exclude_args = HashMap::new();
        exclude_args.insert("U".to_string(), keyof_t);
        exclude_args.insert("T".to_string(), Type::StringLiteral("b".to_string()));

        let excluded = evaluate_conditional_type(
            &Type::TypeParameter("U".to_string()),
            &Type::TypeParameter("T".to_string()),
            &Type::Never,
            &Type::TypeParameter("U".to_string()),
            &exclude_args,
        );

        // excluded = "a" | "c"
        match &excluded {
            Type::Union(members) => {
                assert_eq!(members.len(), 2);
                assert!(members.contains(&Type::StringLiteral("a".to_string())));
                assert!(members.contains(&Type::StringLiteral("c".to_string())));
            }
            _ => panic!("Expected union, got {:?}", excluded),
        }

        // Now Pick with the excluded keys
        args.insert("K".to_string(), excluded);
        let template = Type::IndexedAccess(
            Arc::new(Type::TypeParameter("T".to_string())),
            Arc::new(Type::TypeParameter("P".to_string())),
        );

        let result = evaluate_mapped_type(
            "P",
            &Type::TypeParameter("K".to_string()),
            Some(&template),
            None,
            None,
            None,
            &args,
        );

        if let Type::ObjectType(info) = &result {
            assert_eq!(info.properties.len(), 2);
            assert!(info.properties.iter().any(|(n, _)| n == "a"));
            assert!(info.properties.iter().any(|(n, _)| n == "c"));
            assert!(!info.properties.iter().any(|(n, _)| n == "b"));
        } else {
            panic!("Expected ObjectType");
        }
    }

    // --- Nested conditional type ---

    #[test]
    fn test_nested_conditional() {
        // T extends string ? "str" : T extends number ? "num" : "other"
        // with T = number => "num"
        let inner_cond = Type::Conditional {
            check: Arc::new(Type::TypeParameter("T".to_string())),
            extends: Arc::new(Type::Number),
            true_type: Arc::new(Type::StringLiteral("num".to_string())),
            false_type: Arc::new(Type::StringLiteral("other".to_string())),
        };

        let check = Type::TypeParameter("T".to_string());
        let extends = Type::String;
        let true_type = Type::StringLiteral("str".to_string());

        let mut type_args = HashMap::new();
        type_args.insert("T".to_string(), Type::Number);

        let result =
            evaluate_conditional_type(&check, &extends, &true_type, &inner_cond, &type_args);
        // number does not extend string, so we evaluate the false branch
        // The false branch is itself a conditional: number extends number ? "num" : "other"
        // But evaluate_conditional_type substitutes first, so the false_type gets substituted
        // and then we need resolve_type_level_computation to evaluate nested conditionals
        let resolved = resolve_type_level_computation(&result, &type_args);
        assert_eq!(resolved, Type::StringLiteral("num".to_string()));
    }

