    #[test]
    fn test_instanceof_rejects_definitely_invalid_operands() {
        let out = parse_and_check(
            r#"
            declare const anyValue: any;
            declare const primitiveUnion: number | string;
            declare const objectValue: {};
            declare const Promise: {};
            class C {}
            declare const instance: C;
            primitiveUnion instanceof Object;
            anyValue instanceof 1;
            anyValue instanceof objectValue;
            anyValue instanceof Promise;
            anyValue instanceof instance;
            "#,
        );
        assert_eq!(out.diagnostics.iter().filter(|d| d.code == 2358).count(), 1);
        assert_eq!(out.diagnostics.iter().filter(|d| d.code == 2359).count(), 4);
    }

    #[test]
    fn test_instanceof_accepts_uncertain_and_custom_has_instance_operands() {
        let out = parse_and_check(
            r#"
            declare const anyValue: any;
            declare const objectValue: object | string;
            declare const callable: { (): void };
            declare const constructable: { new (): object };
            declare const custom: { [Symbol.hasInstance](value: unknown): boolean };
            class FunctionSubclass extends Function {}
            declare const functionSubclass: FunctionSubclass;
            function generic<T>(value: T, rhs: T) {
                value instanceof Object;
                anyValue instanceof rhs;
            }
            objectValue instanceof Object;
            anyValue instanceof callable;
            anyValue instanceof constructable;
            anyValue instanceof custom;
            anyValue instanceof functionSubclass;
            "#,
        );
        assert!(
            out.diagnostics
                .iter()
                .all(|d| !matches!(d.code, 2358 | 2359)),
            "unexpected instanceof diagnostics: {:?}",
            out.diagnostics
        );
    }

