    #[test]
    fn test_contextual_typing_callback_param() {
        // Callback parameter gets type from function signature
        let src = r#"
function forEach(arr: number[], cb: (item: number) => void) {}
forEach([1, 2], (x) => { let y: number = x; });
"#;
        check_no_errors(src);
    }

    #[test]
    fn test_contextual_typing_callback_returns_correct_type() {
        // The callback parameter 'x' should be typed as 'number' from context
        let src = r#"
function map(arr: number[], cb: (item: number) => string) {}
map([1, 2], (x) => "hello");
"#;
        check_no_errors(src);
    }

    #[test]
    fn test_contextual_typing_callback_wrong_usage() {
        // Using contextually-typed param incorrectly should still error
        let src = r#"
function process(cb: (item: number) => void) {}
process((x) => { let y: string = x; });
"#;
        check_has_error(src, 2322);
    }

    #[test]
    fn test_contextual_typing_explicit_annotation_wins() {
        // Explicit parameter annotation should override contextual type
        let src = r#"
function run(cb: (item: number) => void) {}
run((x: string) => {});
"#;
        // x is explicitly string, but context wants number - the function call
        // should produce an arg-not-assignable error
        check_has_error(src, 2345);
    }

    #[test]
    fn test_contextual_typing_multiple_params() {
        // Multiple callback parameters get contextual types
        let src = r#"
function combine(cb: (a: number, b: string) => void) {}
combine((x, y) => { let n: number = x; let s: string = y; });
"#;
        check_no_errors(src);
    }

    #[test]
    fn test_array_method_callbacks_have_standard_arity() {
        let src = r#"
const xs: number[] = [1, 2, 3];
xs.reduce((acc: number, value: number, index: number, array: number[]) =>
    acc + value + index + array.length, 0);
xs.forEach((value: number, index: number, array: number[]) =>
    void (value + index + array.length));
xs.map((value: number, index: number, array: number[]) =>
    value + index + array.length);
xs.filter((value: number, index: number, array: number[]) =>
    value > index + array.length);
xs.find((value: number, index: number, array: number[]) =>
    value > index + array.length);
xs.findIndex((value: number, index: number, array: number[]) =>
    value > index + array.length);
xs.some((value: number, index: number, array: number[]) =>
    value > index + array.length);
xs.every((value: number, index: number, array: number[]) =>
    value > index + array.length);
"#;
        let output = parse_and_check_with_opts(
            src,
            CompilerOptions {
                target: Some(tsc_rs_ast::ScriptTarget::ES2015),
                ..CompilerOptions::default()
            },
        );
        assert!(output.diagnostics.is_empty(), "{:?}", output.diagnostics);
    }

    #[test]
    fn test_contextual_typing_call_new_and_super_callbacks_once() {
        let out = parse_and_check(
            r#"
function call(cb: (value: string) => void) {}
class Base {
    constructor(cb: (value: string) => void) {}
}
class Derived extends Base {
    constructor() {
        call(value => { value = 1; });
        super(value => { value = 2; });
    }
}
new Base(value => { value = 3; });
"#,
        );
        let errors: Vec<_> = out.diagnostics.iter().filter(|d| d.code == 2322).collect();
        assert_eq!(
            errors.len(),
            3,
            "each call/new/super callback must be checked once: {:?}",
            out.diagnostics
        );
    }

    #[test]
    fn test_contextual_typing_rest_callbacks_for_call_new_and_super() {
        let out = parse_and_check(
            r#"
function call(...callbacks: ((value: string) => void)[]) {}
class Base {
    constructor(...callbacks: ((value: string) => void)[]) {}
}
class Derived extends Base {
    constructor() {
        call(value => { value = 1; }, value => { value = 2; });
        super(value => { value = 3; }, value => { value = 4; });
    }
}
new Base(value => { value = 5; }, value => { value = 6; });
"#,
        );
        let errors: Vec<_> = out.diagnostics.iter().filter(|d| d.code == 2322).collect();
        assert_eq!(
            errors.len(),
            6,
            "rest callback arguments must share the element context: {:?}",
            out.diagnostics
        );
    }

    #[test]
    fn test_constructor_contextual_typing_unknown_base_is_conservative() {
        let out = parse_and_check(
            r#"
class SuperDerived extends Response {
    constructor() {
        super(value => { value = 1; });
    }
}
class NewDerived extends Response {}
new NewDerived(value => { value = 2; });
"#,
        );
        assert!(
            out.diagnostics.is_empty(),
            "an unresolved constructor must not invent context or arity: {:?}",
            out.diagnostics
        );
    }

    #[test]
    fn test_constructor_contextual_typing_generic_and_overload_controls() {
        let out = parse_and_check(
            r#"
class Generic<T> {
    constructor(cb: (value: T) => void) {}
}
new Generic(value => { value = 1; });

class Overloaded {
    constructor(cb: (value: string) => void);
    constructor(cb: (value: number) => void);
    constructor(cb: (value: any) => void) {}
}
new Overloaded(value => { value = 2; });
"#,
        );
        assert!(
            out.diagnostics.is_empty(),
            "generic and overloaded constructors stay on the conservative path: {:?}",
            out.diagnostics
        );
    }

    #[test]
    fn test_inherited_constructor_contextual_typing_rejects_heritage_cycle() {
        let out = parse_and_check(
            r#"
class A extends B {}
class B extends A {
    constructor(cb: (value: string) => void) { super(cb); }
}
new A(value => { value = 1; });
"#,
        );
        assert!(
            out.diagnostics
                .iter()
                .all(|diagnostic| diagnostic.code != 2322),
            "a cyclic inherited constructor must not provide context: {:?}",
            out.diagnostics
        );
    }

    #[test]
    fn test_direct_constructor_contextual_typing_survives_self_cycle() {
        let out = parse_and_check(
            r#"
class SelfCycle extends SelfCycle {
    constructor(cb: (value: string) => void) { super(cb); }
}
new SelfCycle(value => { value = 1; });
"#,
        );
        let errors: Vec<_> = out.diagnostics.iter().filter(|d| d.code == 2322).collect();
        assert_eq!(
            errors.len(),
            1,
            "a direct construct signature remains contextual despite its heritage error: {:?}",
            out.diagnostics
        );
    }

