    #[test]
    fn test_switch_true_tracks_exhaustive_default_and_fallthrough() {
        let output = parse_and_check_with_opts(
            r#"
            class First { first = 1; }
            class Second { second = 2; }

            function test(value: First | Second) {
                switch (true) {
                    case value instanceof First: {
                        break;
                    }
                    case value instanceof Second: {
                        break;
                    }
                    default:
                        const exhaustive: never = value;
                }

                switch (true) {
                    case value instanceof First:
                        break;
                    case value instanceof Second:
                        // Falls through, so the default is reachable as Second.
                    default:
                        const reachable: never = value;
                }
            }
            "#,
            strict_null_opts(),
        );
        let assignment_errors: Vec<_> = output
            .diagnostics
            .iter()
            .filter(|diag| diag.code == 2322)
            .collect();
        assert_eq!(
            assignment_errors.len(),
            1,
            "Expected only the fallthrough assignment error, got: {:?}",
            output.diagnostics
        );
    }

