    #[test]
    fn test_union_property_must_exist_on_every_known_member() {
        let output = parse_and_check(
            r#"
            interface Left { kind: "left"; common: string; left: number; }
            interface Right { kind: "right"; common: string; right: number; }
            declare const value: Left | Right;
            value.common;
            value.left;

            type Both = Left | Right;
            function throughSwitch(value: Both) {
                switch (true) {
                    case value.kind === "left":
                        // fallthrough
                    case value.kind === "right":
                        value.right;
                }
            }
            "#,
        );
        let property_errors: Vec<_> = output
            .diagnostics
            .iter()
            .filter(|diag| diag.code == 2339)
            .collect();
        assert_eq!(
            property_errors.len(),
            1,
            "Diagnostics: {:?}",
            output.diagnostics
        );
        assert!(property_errors[0].message.contains("Both"));
        assert!(property_errors[0].message.contains("type 'Left'"));
    }

