    #[test]
    fn test_template_literal_assignable_to_string() {
        // A TemplateLiteral type should be assignable to string
        let tl = Type::TemplateLiteral {
            quasis: vec!["".into(), "Changed".into()].into(),
            types: vec![Type::String].into(),
        };
        let checker = TypeChecker::new();
        assert!(checker.is_assignable_to(&tl, &Type::String));
        // A matching string literal should be assignable to the template
        assert!(checker.is_assignable_to(&Type::StringLiteral("nameChanged".into()), &tl,));
        // A non-matching string literal should NOT be assignable
        assert!(!checker.is_assignable_to(&Type::StringLiteral("fooBar".into()), &tl,));
    }

