    #[test]
    fn test_recursive_type_json_no_stack_overflow() {
        // type Json = string | number | boolean | null | Json[] | { [k: string]: Json }
        // The key test: this must NOT cause a stack overflow.
        let _ = parse_and_check(
            r#"
            type Json = string | number | boolean | null | Json[] | { [k: string]: Json };
            let x: Json = "hello";
            let y: Json = 42;
            let z: Json = [1, "two", true];
        "#,
        );
    }

    #[test]
    fn test_recursive_type_tree_no_stack_overflow() {
        // type Tree<T> = { value: T, children: Tree<T>[] }
        // Must not stack overflow.
        let _ = parse_and_check(
            r#"
            type Tree<T> = { value: T, children: Tree<T>[] };
            let t: Tree<number> = { value: 1, children: [] };
        "#,
        );
    }

    #[test]
    fn test_recursive_conditional_type_no_stack_overflow() {
        // Circular conditional type that could infinitely recurse. Must not overflow.
        let _ = parse_and_check(
            r#"
            type DeepPartial<T> = T extends object ? { [K in keyof T]?: DeepPartial<T[K]> } : T;
            let x: DeepPartial<{ a: number }> = {};
        "#,
        );
    }

    #[test]
    fn test_mutually_recursive_types_no_stack_overflow() {
        // Two types that reference each other. Must not overflow.
        check_no_errors(
            r#"
            type A = { b: B };
            type B = { a: A };
            let x: A = {} as A;
        "#,
        );
    }

    #[test]
    fn test_deeply_nested_type_no_stack_overflow() {
        // A type that nests itself deeply. Must not overflow.
        let _ = parse_and_check(
            r#"
            type Nested<T> = { inner: Nested<T> | T };
            let x: Nested<string> = {} as Nested<string>;
        "#,
        );
    }

    // -----------------------------------------------------------------------
    // Arena tests
    // -----------------------------------------------------------------------

    #[test]
    fn test_arena_primitive_interning() {
        let mut tc = TypeChecker::new();
        // Common primitives should return their well-known IDs
        assert_eq!(tc.intern_type(Type::Any), TYPE_ANY);
        assert_eq!(tc.intern_type(Type::Number), TYPE_NUMBER);
        assert_eq!(tc.intern_type(Type::String), TYPE_STRING);
        assert_eq!(tc.intern_type(Type::Boolean), TYPE_BOOLEAN);
        assert_eq!(tc.intern_type(Type::Void), TYPE_VOID);
        assert_eq!(tc.intern_type(Type::Undefined), TYPE_UNDEFINED);
        assert_eq!(tc.intern_type(Type::Null), TYPE_NULL);
        assert_eq!(tc.intern_type(Type::Never), TYPE_NEVER);
        assert_eq!(tc.intern_type(Type::Error), TYPE_ERROR);
        // Arena should not have grown beyond the initial pre-allocated types
        assert_eq!(tc.arena.len(), 13); // 13 pre-allocated primitive types
    }

    #[test]
    fn test_arena_deduplication() {
        let mut tc = TypeChecker::new();
        // Intern a compound type twice - should get the same ID
        let id1 = tc.intern_type(Type::Array(Arc::new(Type::Number)));
        let id2 = tc.intern_type(Type::Array(Arc::new(Type::Number)));
        assert_eq!(id1, id2);
        // Different compound type should get a different ID
        let id3 = tc.intern_type(Type::Array(Arc::new(Type::String)));
        assert_ne!(id1, id3);
    }

    #[test]
    fn test_arena_get_type() {
        let mut tc = TypeChecker::new();
        assert_eq!(tc.get_type(TYPE_NUMBER), &Type::Number);
        assert_eq!(tc.get_type(TYPE_STRING), &Type::String);
        let id = tc.intern_type(Type::Array(Arc::new(Type::Boolean)));
        assert_eq!(tc.get_type(id), &Type::Array(Arc::new(Type::Boolean)));
    }

    #[test]
    fn test_arena_scope_vars_use_type_id() {
        // Verify that declare_var + lookup_var round-trips through the arena
        let mut tc = TypeChecker::new();
        tc.declare_var("x", Type::Number);
        tc.declare_var("y", Type::Array(Arc::new(Type::String)));
        assert_eq!(tc.lookup_var("x"), Some(&Type::Number));
        assert_eq!(
            tc.lookup_var("y"),
            Some(&Type::Array(Arc::new(Type::String)))
        );
        assert_eq!(tc.lookup_var("z"), None);
    }

    #[test]
    fn test_arena_narrow_var() {
        let mut tc = TypeChecker::new();
        tc.declare_var("x", Type::Union(vec![Type::String, Type::Null].into()));
        tc.push_scope();
        tc.narrow_var("x", Type::String);
        assert_eq!(tc.lookup_var("x"), Some(&Type::String));
        tc.pop_scope();
        // After popping scope, original type should be visible again
        assert_eq!(
            tc.lookup_var("x"),
            Some(&Type::Union(vec![Type::String, Type::Null].into()))
        );
    }
