    #[test]
    fn test_type_guard_basic_is_string() {
        // Basic type guard: isString(x) narrows x to string in if-branch
        check_no_errors(
            r#"
            function isString(x: unknown): x is string {
                return typeof x === "string";
            }
            function test(val: unknown) {
                if (isString(val)) {
                    let s: string = val;
                }
            }
        "#,
        );
    }

    #[test]
    fn test_type_guard_narrows_union() {
        // Type guard narrows a union type
        check_no_errors(
            r#"
            function isNumber(x: string | number): x is number {
                return typeof x === "number";
            }
            function test(val: string | number) {
                if (isNumber(val)) {
                    let n: number = val;
                }
            }
        "#,
        );
    }

    #[test]
    fn test_type_guard_asserts() {
        // asserts x is T narrows after the call
        check_no_errors(
            r#"
            function assertIsString(x: unknown): asserts x is string {
                if (typeof x !== "string") throw "not string";
            }
            function test(val: unknown) {
                assertIsString(val);
                let s: string = val;
            }
        "#,
        );
    }

