    // -----------------------------------------------------------------------
    // Discriminated union narrowing
    // -----------------------------------------------------------------------

    #[test]
    fn test_discriminated_union_narrowing_basic() {
        // Basic discriminated union: if (x.kind === "circle") narrows x
        check_no_errors(
            r#"
            type Circle = { kind: "circle"; radius: number };
            type Square = { kind: "square"; side: number };
            type Shape = Circle | Square;

            function area(s: Shape): number {
                if (s.kind === "circle") {
                    let r: number = s.radius;
                    return r;
                } else {
                    let side: number = s.side;
                    return side;
                }
            }
        "#,
        );
    }

    #[test]
    fn test_discriminated_union_narrowing_string_literal() {
        // String literal discriminant narrows correctly
        check_no_errors(
            r#"
            type Cat = { type: "cat"; meow: boolean };
            type Dog = { type: "dog"; bark: boolean };
            type Animal = Cat | Dog;

            function handle(a: Animal) {
                if (a.type === "cat") {
                    let m: boolean = a.meow;
                }
            }
        "#,
        );
    }

    #[test]
    fn test_discriminated_union_narrowing_number_literal() {
        // Number literal discriminant
        check_no_errors(
            r#"
            type Success = { code: 200; data: string };
            type NotFound = { code: 404; message: string };
            type Response = Success | NotFound;

            function handle(r: Response) {
                if (r.code === 200) {
                    let d: string = r.data;
                }
            }
        "#,
        );
    }

    #[test]
    fn test_discriminated_union_narrowing_multiple_members() {
        // Multiple union members matching same discriminant
        check_no_errors(
            r#"
            type Circle = { kind: "round"; radius: number };
            type Oval = { kind: "round"; rx: number; ry: number };
            type Square = { kind: "angular"; side: number };
            type Shape = Circle | Oval | Square;

            function handle(s: Shape) {
                if (s.kind === "angular") {
                    let side: number = s.side;
                }
            }
        "#,
        );
    }

    #[test]
    fn test_discriminated_union_narrowing_not_equal() {
        // !== should narrow in reverse
        check_no_errors(
            r#"
            type Circle = { kind: "circle"; radius: number };
            type Square = { kind: "square"; side: number };
            type Shape = Circle | Square;

            function handle(s: Shape) {
                if (s.kind !== "circle") {
                    let side: number = s.side;
                }
            }
        "#,
        );
    }

    // -----------------------------------------------------------------------
    // Switch statement narrowing
    // -----------------------------------------------------------------------

    #[test]
    fn test_switch_discriminated_union_narrowing() {
        // switch(s.kind) narrows s in each case
        check_no_errors(
            r#"
            type Circle = { kind: "circle"; radius: number };
            type Square = { kind: "square"; side: number };
            type Shape = Circle | Square;

            function area(s: Shape): number {
                switch (s.kind) {
                    case "circle":
                        let r: number = s.radius;
                        return r;
                    case "square":
                        let side: number = s.side;
                        return side;
                }
                return 0;
            }
        "#,
        );
    }

    #[test]
    fn test_switch_exhaustive_discriminated_union() {
        // Exhaustive switch covers all cases
        check_no_errors(
            r#"
            type A = { tag: "a"; x: number };
            type B = { tag: "b"; y: string };
            type C = { tag: "c"; z: boolean };
            type ABC = A | B | C;

            function handle(v: ABC) {
                switch (v.tag) {
                    case "a":
                        let x: number = v.x;
                        break;
                    case "b":
                        let y: string = v.y;
                        break;
                    case "c":
                        let z: boolean = v.z;
                        break;
                }
            }
        "#,
        );
    }

    #[test]
    fn test_switch_number_discriminant() {
        // switch on number literal discriminant
        check_no_errors(
            r#"
            type Ok = { status: 200; body: string };
            type Err = { status: 500; error: string };
            type Resp = Ok | Err;

            function handle(r: Resp) {
                switch (r.status) {
                    case 200:
                        let b: string = r.body;
                        break;
                    case 500:
                        let e: string = r.error;
                        break;
                }
            }
        "#,
        );
    }

    #[test]
    fn test_nested_discriminated_union() {
        // Nested if-else chain with discriminants
        check_no_errors(
            r#"
            type Circle = { kind: "circle"; radius: number };
            type Square = { kind: "square"; side: number };
            type Triangle = { kind: "triangle"; base: number; height: number };
            type Shape = Circle | Square | Triangle;

            function describe(s: Shape): string {
                if (s.kind === "circle") {
                    let r: number = s.radius;
                    return "circle";
                } else if (s.kind === "square") {
                    let side: number = s.side;
                    return "square";
                } else {
                    let b: number = s.base;
                    let h: number = s.height;
                    return "triangle";
                }
            }
        "#,
        );
    }

