    #[test]
    fn test_es2015_stdlib_merges_typed_array_literal_tag() {
        let mut options = CompilerOptions::default();
        options.target = Some(tsc_rs_ast::ScriptTarget::ES2015);
        let libraries = load_stdlib_sources(&options);
        if libraries.is_empty() {
            return;
        }
        let parsed: Vec<_> = libraries
            .iter()
            .map(|library| tsc_rs_parser::parse(&library.file_name, &library.source))
            .collect();
        let references: Vec<_> = parsed.iter().collect();
        let mut checker = TypeChecker::new();
        checker.inject_external_types(&references);

        let info = checker
            .interface_info
            .get("Int8Array")
            .expect("expected merged Int8Array interface");
        let properties: Vec<_> = info
            .object_type
            .properties
            .iter()
            .map(|(name, ty)| (name.as_str(), ty.display_string()))
            .collect();
        assert!(
            properties
                .iter()
                .any(|(name, ty)| *name == "[Symbol.toStringTag]" && ty == "\"Int8Array\""),
            "Int8Array properties: {properties:?}"
        );
    }

    #[test]
    fn test_interface_merge_preserves_donor_clone_copy_on_write() {
        let first = tsc_rs_parser::parse("first.d.ts", "interface Merged { first: string }");
        let second = tsc_rs_parser::parse("second.d.ts", "interface Merged { second: number }");
        let mut donor = TypeChecker::new();
        donor.inject_external_types(&[&first]);
        let mut augmented = donor.clone();
        assert!(Arc::ptr_eq(
            &donor.interface_info,
            &augmented.interface_info
        ));

        augmented.inject_external_types(&[&second]);
        assert!(!Arc::ptr_eq(
            &donor.interface_info,
            &augmented.interface_info
        ));
        let donor_properties = &donor
            .interface_info
            .get("Merged")
            .expect("donor Merged")
            .object_type
            .properties;
        let augmented_properties = &augmented
            .interface_info
            .get("Merged")
            .expect("augmented Merged")
            .object_type
            .properties;
        assert_eq!(
            donor_properties
                .iter()
                .map(|(name, _)| name.as_str())
                .collect::<Vec<_>>(),
            ["first"]
        );
        assert_eq!(
            augmented_properties
                .iter()
                .map(|(name, _)| name.as_str())
                .collect::<Vec<_>>(),
            ["first", "second"]
        );
    }

    #[test]
    fn test_interface_merge_deduplicates_flattened_overloads() {
        let first = tsc_rs_parser::parse(
            "first.d.ts",
            "interface Merged { f(value: string): string }",
        );
        let second = tsc_rs_parser::parse(
            "second.d.ts",
            "interface Merged { f(value: number): number }",
        );
        let mut checker = TypeChecker::new();
        checker.inject_external_types(&[&first, &second, &second]);
        let property = checker
            .interface_info
            .get("Merged")
            .and_then(|info| {
                info.object_type
                    .properties
                    .iter()
                    .find(|(name, _)| name == "f")
            })
            .expect("Merged.f");
        let Type::Intersection(signatures) = property.1.as_ref() else {
            panic!("expected overload intersection, got {:?}", property.1);
        };
        assert_eq!(signatures.len(), 2, "signatures: {signatures:?}");
    }

    #[test]
    fn test_well_known_symbol_keys_remain_distinct_after_merge() {
        let base = tsc_rs_parser::parse(
            "base.d.ts",
            "interface SymbolConstructor {\n\
             readonly iterator: unique symbol;\n\
             readonly toStringTag: unique symbol;\n\
             }\n\
             declare var Symbol: SymbolConstructor;\n",
        );
        let augmentation = tsc_rs_parser::parse(
            "augmentation.d.ts",
            "interface Tagged {\n\
             readonly [Symbol.iterator]: () => string;\n\
             readonly [Symbol.toStringTag]: \"Tagged\";\n\
             }\n",
        );
        let mut checker = TypeChecker::new();
        checker.inject_external_types(&[&base, &augmentation]);
        let keys: Vec<_> = checker
            .interface_info
            .get("Tagged")
            .expect("Tagged")
            .object_type
            .properties
            .iter()
            .map(|(name, _)| name.as_str())
            .collect();
        assert!(keys.contains(&"[Symbol.iterator]"), "keys: {keys:?}");
        assert!(keys.contains(&"[Symbol.toStringTag]"), "keys: {keys:?}");
    }

    fn check_with_declaration_donor(declarations: &str, source: &str) -> TypeCheckOutput {
        let declarations = tsc_rs_parser::parse("ambient.d.ts", declarations);
        let source = tsc_rs_parser::parse("consumer.ts", source);
        let symbols = tsc_rs_symbols::bind(&source);
        let mut checker = TypeChecker::new();
        checker.inject_external_types(&[&declarations]);
        checker.take_diagnostics();
        checker.check(&source, &symbols)
    }

